package com.travbook.platform.security;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;
class StayReturnPathTest {
 @Test void onlyKnownInternalStayResourcesAreAccepted(){String id="11111111-1111-4111-8111-111111111111";assertThat(StayReturnPath.valid("/stays/quotes/"+id)).isTrue();assertThat(StayReturnPath.valid("/stays/quotes/new?offers="+id+"&requestId="+id)).isTrue();for(String value:new String[]{"https://attacker.test","//attacker.test","/stays/trips?next=https://attacker.test","/stays/quotes/"+id+"#fragment","/stays/quotes/new?offers=invalid&requestId="+id})assertThat(StayReturnPath.valid(value)).isFalse();}
 @Test void journeyPathsRejectUnknownQueries(){String id="11111111-1111-4111-8111-111111111111";for(String path:new String[]{"/journeys/trips","/journeys/bookings/"+id,"/journeys/new?kind=CAB&sourceId="+id+"&offerId="+id+"&requestId="+id,"/journeys/new?kind=BUS&sourceId="+id+"&offerId="+id+"&seats=L1%2CL2&boardingId=DELHI-CENTRE&droppingId=JAIPUR-CENTRE&requestId="+id}){assertThat(StayReturnPath.valid(path)).isTrue();assertThat(StayReturnPath.valid(path+"&next=https://evil.test")).isFalse();}assertThat(StayReturnPath.valid("/journeys/new?kind=HOLIDAY&sourceId="+id+"&requestId="+id+"&sourceId="+id)).isFalse();}
 @Test void railReturnPathRejectsInjectedDestinationsAndPersonalData(){String id="11111111-1111-4111-8111-111111111111",path="/rail-tickets/quotes/new?journey="+id+"&travelClass=SL&quota=GENERAL&requestId="+id;assertThat(StayReturnPath.valid(path)).isTrue();assertThat(StayReturnPath.valid("/rail-tickets/bookings/"+id)).isTrue();assertThat(StayReturnPath.valid("/rail-tickets/trips")).isTrue();for(String bad:new String[]{path+"&name=Alex",path+"#fragment",path.replace("SL","INVALID"),"//evil.test/rail-tickets/trips","/rail-tickets/trips?next=//evil.test"})assertThat(StayReturnPath.valid(bad)).isFalse();}
}
